mapper.select:
SELECT * FROM booking_guest
WHERE booking_id = #{bookingId}
ORDER BY id

SELECT g.* FROM booking_guest g
JOIN booking b ON g.booking_id = b.id
WHERE b.visit_date = #{date}
  AND b.status != 'CANCELLED'
  AND g.id_card = #{idCard}

SELECT COUNT(*) FROM booking_guest g
JOIN booking b ON g.booking_id = b.id
WHERE b.visit_date = #{date}
  AND b.slot = #{slot}
  AND b.status = 'ACTIVE'
